import {decodeCTC,textRegions} from './paddle-ocr-core.js?v=20261027motion';
let ort,detector,recognizer,characters;
const runtime='https://cdn.jsdelivr.net/npm/onnxruntime-web@1.22.0/dist/';
const urls={det:'https://huggingface.co/PaddlePaddle/PP-OCRv5_mobile_det_onnx/resolve/e6f4fa85f00e168c862bc462aebca69eef9b3d3d/inference.onnx',rec:'https://huggingface.co/PaddlePaddle/PP-OCRv5_mobile_rec_onnx/resolve/ed152b8b495f84de93cda5709d768548a9127622/inference.onnx'};
const progress=text=>postMessage({type:'progress',text});
async function model(url){let cache;try{cache=await caches.open('clippilot-paddle-v5-1');const saved=await cache.match(url);if(saved)return saved.arrayBuffer()}catch{}const response=await fetch(url);if(!response.ok)throw Error('开源 OCR 模型下载失败：'+response.status);if(cache)await cache.put(url,response.clone()).catch(()=>{});return response.arrayBuffer()}
async function load(){progress('正在下载 PaddleOCR 检测、识别模型（约 22 MB），不上传画面…');ort=await import(runtime+'ort.wasm.min.mjs');ort.env.wasm.wasmPaths=runtime;ort.env.wasm.numThreads=1;ort.env.logLevel='error';const [det,rec,chars]=await Promise.all([model(urls.det),model(urls.rec),fetch(new URL('./paddle-characters.json',import.meta.url)).then(r=>{if(!r.ok)throw Error('OCR 字符表读取失败');return r.json()})]);characters=chars;detector=await ort.InferenceSession.create(det,{executionProviders:['wasm'],logSeverityLevel:3});recognizer=await ort.InferenceSession.create(rec,{executionProviders:['wasm'],logSeverityLevel:3});return{engine:'PP-OCRv5_mobile',detector:urls.det,recognizer:urls.rec}}
function input(canvas,det){const {width:w,height:h}=canvas,p=canvas.getContext('2d',{willReadFrequently:true}).getImageData(0,0,w,h).data,a=new Float32Array(w*h*3);for(let i=0;i<w*h;i++)for(let c=0;c<3;c++){const v=p[i*4+(2-c)]/255;a[c*w*h+i]=det?(v-[.485,.456,.406][c])/[.229,.224,.225][c]:(v-.5)/.5}return new ort.Tensor('float32',a,[1,3,h,w])}
async function recognize({pixels,width,height}){const source=new OffscreenCanvas(width,height);source.getContext('2d').putImageData(new ImageData(new Uint8ClampedArray(pixels),width,height),0,0);const ratio=Math.min(1,960/Math.max(width,height)),w=Math.max(32,Math.round(width*ratio/32)*32),h=Math.max(32,Math.round(height*ratio/32)*32),canvas=new OffscreenCanvas(w,h);canvas.getContext('2d').drawImage(source,0,0,w,h);const out=await detector.run({[detector.inputNames[0]]:input(canvas,true)}),heat=out[detector.outputNames[0]],hh=heat.dims.at(-2),ww=heat.dims.at(-1),regions=textRegions(heat.data,ww,hh),lines=[];for(const b of regions){const x=b.x/ww*width,y=b.y/hh*height,bw=b.w/ww*width,bh=b.h/hh*height,pad=bh*.3,left=Math.max(0,x-pad),top=Math.max(0,y-pad),right=Math.min(width,x+bw+pad),bottom=Math.min(height,y+bh+pad),cw=right-left,ch=bottom-top,rw=Math.min(1600,Math.ceil(cw/ch*48)),full=Math.max(320,rw),crop=new OffscreenCanvas(full,48),ctx=crop.getContext('2d');ctx.fillStyle='rgb(127,127,127)';ctx.fillRect(0,0,full,48);ctx.drawImage(source,left,top,cw,ch,0,0,rw,48);const result=await recognizer.run({[recognizer.inputNames[0]]:input(crop,false)}),r=result[recognizer.outputNames[0]],decoded=decodeCTC(r.data,r.dims,characters);if(decoded.text.trim())lines.push({...decoded,bbox:{x0:x,y0:y,x1:x+bw,y1:y+bh}})}return{data:{text:lines.map(l=>l.text).join('\n'),blocks:[{paragraphs:[{lines}]}]}}}
self.onmessage=async({data})=>{try{const result=data.type==='load'?await load():data.type==='recognize'?await recognize(data):null;postMessage({type:'result',id:data.id,result})}catch(e){postMessage({type:'error',id:data.id,text:e.message||String(e)})}};
